/** @param {{des: object}} api */
export default function tower3({ des, selection, luaList }) {
    des.level_init({ style: 'solidfill', fg: ' ' });

    des.level_flags('mazelevel', 'noteleport', 'hardfloor', 'solidify');
    des.map({
        halign: 'half-left', valign: 'center', map: `    --- --- ---    
    |.| |.| |.|    
  ---S---S---S---  
  |.S.........S.|  
-----.........-----
|...|.........+...|
|.---.........---.|
|.|.S.........S.|.|
|.---S---S---S---.|
|...|.|.|.|.|.|...|
---.---.---.---.---
  |.............|  
  ---------------  
`,
    });
    // Random places are the 10 niches
    // luaList keeps Lua's 1-based indices, so place[n] means the same here.
    const place = luaList(
        [5, 1], [9, 1], [13, 1], [3, 3], [15, 3], [3, 7], [15, 7], [5, 9], [9, 9], [13, 9]
    );

    des.levregion({ type: 'branch', region: [2, 5, 2, 5] });
    des.ladder('up', 5, 7);
    // Entry door is, of course, locked
    des.door('locked', 14, 5);
    // Let's put a dragon behind the door, just for the fun...
    des.monster('D', 13, 5);
    des.monster({ x: 12, y: 4 });
    des.monster({ x: 12, y: 6 });
    des.monster();
    des.monster();
    des.monster();
    des.monster();
    des.monster();
    des.monster();
    des.object('long sword', place[4]);
    des.trap({ coord: place[4] });
    des.object('lock pick', place[1]);
    des.trap({ coord: place[1] });
    des.object('elven cloak', place[2]);
    des.trap({ coord: place[2] });
    des.object('blindfold', place[3]);
    des.trap({ coord: place[3] });
    // Walls in the tower are non diggable
    des.non_diggable(selection.area(0, 0, 18, 12));
}
